@js:
var m = String(book.intro).match(/来源◖(\d+)◗/);
var xu = (m && m[1]) ? m[1] : '0';
var gridId = (xu === '1') ? 'grid-1' : 'grid-0';
var start = src.indexOf('<div id="' + gridId + '"');
var end = src.indexOf('<div id="grid-', start + 10);
if (end < 0) { end = src.indexOf('<script', start + 10); }
if (end < 0) { end = src.length; }
var block = src.substring(start, end);
var list = [];
var re = new RegExp('<a href="(/video/\\d+/\\d+)"[^>]*class="episode-item"[^>]*>\\s*([^<]+)\\s*</a>', 'g');
var m;
while ((m = re.exec(block)) !== null) {
  list.push({ text: m[2].trim(), href: m[1] });
}
